grid=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
fg={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8}
# square piece color1, L variants colors based missing corner
shapes={1:{(0,0),(0,1),(1,0),(1,1)}, 2:{(0,1),(1,0),(1,1)},3:{(0,0),(0,1),(1,1)},4:{(0,0),(1,0),(1,1)}}
placements=[]
for col,sh in shapes.items():
 for r in range(4):
  for c in range(6):
   p={(r+dr,c+dc) for dr,dc in sh}
   if p<=fg: placements.append((col,p))
# exact covers count
solutions=[]
def rec(left, chosen):
 if not left:
  solutions.append(chosen); return
 cell=min(left)
 for col,p in placements:
  if cell in p and p<=left:
   rec(left-p,chosen+[(col,p)])
rec(fg,[])
len(fg),len(solutions), [[(col, sorted(p)) for col,p in sol] for sol in solutions[:5]]
